# A08 finish, M19: a person can do the whole job on screen. Every test walks the
# real path as a NON-ADMIN user holding the real finance role, through the P03
# endpoints the workspace itself calls (/p03/model/*, /p03/gl/*), against the
# screens evaluated from the registry (static/src/a08/m19.js), never its text.
#
# The write whitelist is generated by the lead from the forms; the `whitelist`
# fixture applies what that generation produces, so these tests do not depend on
# when writable.py was last regenerated.
import json
import re
import shutil
import subprocess
import types
from datetime import date, timedelta
from pathlib import Path

import pytest
from odoo import Command, fields
from odoo.addons.cd_gl_ext.tests.test_e3_vat_close_step import reconciled_vat_return
from odoo.exceptions import AccessError, UserError, ValidationError

pytestmark = [pytest.mark.financial]

ACC_USER = "account.group_account_user"
ACC_MGR = "account.group_account_manager"
BILL = "account.group_account_invoice"
STOCK_MGR = "stock.group_stock_manager"
TIER2 = "cd_entity_config.group_dofa_tier_2"
PE = date(2026, 9, 30)
_SEQ = iter(range(1, 100000))
PORTAL = Path(__file__).resolve().parents[3].parent / "platform" / "cd_p03_portal"
IMPORT = re.compile(r'from\s+"(\./a\d\d/\w+)"')


class Ctx:
    pass


def _user(env, login, groups=()):
    ou = env["operating.unit"].search([], limit=1)
    return (
        env["res.users"]
        .with_context(no_reset_password=True)
        .create(
            {
                "name": login,
                "login": login,
                "group_ids": [
                    (6, 0, [env.ref("base.group_user").id] + [env.ref(g).id for g in groups])
                ],
                "company_ids": [(6, 0, env.company.ids)],
                "company_id": env.company.id,
                "assigned_operating_unit_ids": [(6, 0, ou.ids)],
                "default_operating_unit_id": ou.id,
            }
        )
    )


