@pytest.fixture
def whitelist():
    """What form_fields.py --a08 generates from the forms as they stand."""
    from odoo.addons.cd_p03_portal.controllers import a08, form_fields

    editable = form_fields.editable_by_model()
    saved = {model: conf.get("writable") for model, conf in a08.SURFACES.items()}
    for model, conf in a08.SURFACES.items():
        conf["writable"] = frozenset(editable.get(model, ()))
    try:
        yield
    finally:
        for model, conf in a08.SURFACES.items():
            conf["writable"] = saved[model]


@pytest.fixture
def p03(c, whitelist):
    import odoo.addons.cd_p03_portal.controllers.p03_generic_api as g
    import odoo.addons.cd_p03_portal.controllers.p03_gl_api as gl
    import odoo.addons.cd_p03_portal.controllers.p03_service_order_api as s

    def orig(cls, name):
        f = getattr(cls, name)
        return getattr(f, "original_endpoint", f)

    gctl = g.P03GenericApiController()
    glctl = gl.P03GlApiController()
    old = (getattr(g, "request", None), getattr(s, "request", None), getattr(gl, "request", None))

    def as_user(user):
        req = types.SimpleNamespace(env=c.env(user=user.id))
        g.request = req
        s.request = req
        gl.request = req

    def bind(cls, ctl, name):
        return lambda **kw: orig(cls, name)(ctl, **kw)

    G, L = g.P03GenericApiController, gl.P03GlApiController
    try:
        yield types.SimpleNamespace(
            as_user=as_user,
            write=bind(G, gctl, "model_write"),
            action=bind(G, gctl, "model_action"),
            form=bind(G, gctl, "model_form"),
            records=bind(G, gctl, "model_records"),
            je=bind(L, glctl, "gl_je"),
            je_approve=bind(L, glctl, "gl_je_approve"),
            je_route=bind(L, glctl, "gl_je_route"),
            je_discard=bind(L, glctl, "gl_je_discard"),
            close=bind(L, glctl, "gl_close"),
            close_action=bind(L, glctl, "gl_close_action"),
            statements=bind(L, glctl, "gl_statements"),
            journals=bind(L, glctl, "gl_journals"),
            dimensions=bind(L, glctl, "gl_dimensions"),
            audit=bind(L, glctl, "gl_audit"),
            recon=bind(L, glctl, "gl_recon"),
        )
    finally:
        g.request, s.request, gl.request = old


@pytest.fixture(scope="module")
def screens(tmp_path_factory):
    node = shutil.which("node")
    if not node:
        pytest.skip("node is not available to evaluate the ES-module registry")
    src = PORTAL / "static" / "src"
    tmp = tmp_path_factory.mktemp("p03_m19_op")
    for area in sorted(d for d in src.iterdir() if re.fullmatch(r"a\d\d", d.name)):
        (tmp / area.name).mkdir()
        for js in area.glob("*.js"):
            (tmp / area.name / (js.stem + ".mjs")).write_text(
                js.read_text(encoding="utf-8"), "utf-8"
            )
    meta = (src / "p03_modules_meta.js").read_text(encoding="utf-8")
    (tmp / "meta.mjs").write_text(IMPORT.sub(r'from "\1.mjs"', meta), "utf-8")
    probe = tmp / "probe.mjs"
    probe.write_text(
        "import * as M from './meta.mjs';\n"
        "console.log(JSON.stringify({screens: Object.fromEntries(Object.entries(M.P03_DATA_SCREENS)"
        ".filter(([k]) => k.startsWith('M19'))), chips: M.P03_FORM_CHIPS,"
        " nav: M.P03_MODULES.M19.groups.flatMap((g) => g.screens.map((s) => s.id))}));\n",
        "utf-8",
    )
    out = subprocess.run(  # noqa: S603 - fixed argv: the node binary and our own probe file
        [node, str(probe)], capture_output=True, encoding="utf-8", check=True, timeout=60
    )
    return json.loads(out.stdout)


def form_fields_of(screens, sid):
    return [f for s in screens["screens"][sid]["sections"] for f in s["fields"]]


def assert_screen_operable(p03, screens, list_id, form_id, user, editable, actions):
    """The list is on the menu and calls real surface actions; its + New opens the
    form; the server offers each field as an input, for this user."""
    cfg = screens["screens"][list_id]
    assert list_id in screens["nav"]
    assert screens["chips"]["M19:__by_screen__"][list_id] == form_id
    assert set(actions) <= {a["m"] for a in cfg.get("actions", [])}
    p03.as_user(user)
    listed = p03.records(model=cfg["model"], cols=cfg["cols"])
    assert "error" not in listed, listed
    assert set(cfg["cols"]) <= set(listed["labels"]), "the endpoint dropped a column"
    res = p03.form(model=cfg["model"], fields=form_fields_of(screens, form_id))
    assert "error" not in res, res
    offered = {f["name"]: f for f in res["fields"]}
    assert {f["name"] for f in form_fields_of(screens, form_id)} == set(offered)
    for name in editable:
        assert not offered[name]["readonly"], "%s is not an input" % name


def task_for(c, record, user):
    return c.env["fix.workflow.task"].search(
        [
            ("res_model", "=", record._name),
            ("res_id", "=", record.id),
            ("state", "=", "pending"),
            ("assigned_user_id", "=", user.id),
        ],
        limit=1,
    )


def _vals(c, amount=1000.0, d=None, debit=None, credit=None, ref="A08 op"):
    return {
        "move_type": "entry",
        "journal_id": c.misc.id,
        "date": d or c.today,
        "ref": ref,
        "line_ids": [
            Command.create(
                {"account_id": (debit or c.exp).id, "debit": amount, "credit": 0.0, "name": "p"}
            ),
            Command.create(
                {"account_id": (credit or c.cash).id, "debit": 0.0, "credit": amount, "name": "p"}
            ),
        ],
    }


def _line_dims(c, lines=2):
    """The dimensions a person states on a manual journal: on the linked chart a bank
    line needs a branch, and the screen's journal editor offers one per line."""
    from odoo.addons.cd_gl_ext.models import fix_gl_ext

    branch = fix_gl_ext._default_dimension(c.env, c.co, "branch")
    return {
        i: {"branch_id": branch, "cost_centre": "CORP", "business_line": "SERVICE"}
        for i in range(lines)
    }


def draft_je(c, user, amount=1000.0, **kw):
    from odoo.addons.cd_gl_ext.models.fix_gl_ext import create_journal_entry_draft

    move, log = create_journal_entry_draft(
        c.env(user=user.id), _vals(c, amount, **kw), _line_dims(c), source="manual", reason="op"
    )
    # The preparer's request ends here. One transaction hosts every user in this
    # test, so without this the line writes would flush under whoever acts next,
    # stamp him as their write_uid and make him a preparer of the entry.
    c.env.flush_all()
    return move, log


def sys_post(c, d, amount=10.0):
    m = c.env["account.move"].create(_vals(c, amount, d=d))
    m.action_post()
    return m


def worked_close(c, period_end=PE):
    """A started close with all ten steps done by their owners."""
    evidence = "account.move,%d" % sys_post(c, date(2026, 9, 1)).id
    reconciled_vat_return(c.env, c.co, period_end)  # C10: the VAT step needs a reconciled 9.1
    close = c.env["fix.period.close"].with_user(c.acct).create({"period_end": period_end})
    close.with_user(c.acct).action_generate_standard_steps()
    for ln in close.line_ids:
        owner = c.mgr if ln.sequence == 100 else (c.stk if ln.sequence == 10 else c.acct)
        ln.with_user(owner).action_mark_done(evidence)
    return close


def closed_period(c):
    close = worked_close(c)
    close.with_user(c.acct).action_ready()
    close.with_user(c.mgr).action_close()
    return close


def suspense_entry(c, valuation=1200.0):
    part = c.env["fix.spare.part"].create(
        {
            "name": "LCD %d" % next(_SEQ),
            "part_number": "LCD-%d" % next(_SEQ),
            "part_category": "display",
        }
    )
    return c.env["fix.inventory.valuation.suspense"].create(
        {
            "company_id": c.co.id,
            "product_id": part.id,
            "quantity": 1.0,
            "unit_cost": valuation,
            "total_valuation": valuation,
            "suspense_account_code": "110999",
            # A06 ERP X04/X05: a stock receipt (stock IN, cleared by a credit to
            # the suspense) of the period the close measures
            "entry_type": "receipt",
            "posting_date": PE,
        }
    )


def suspense_account(c):
    A = c.env["account.account"].with_company(c.co)
    return A.search([("code", "=", "110999")], limit=1) or A.create(
        {
            "code": "110999",
            "name": "Suspense",
            "account_type": "asset_current",
            "company_ids": [(6, 0, c.co.ids)],
        }
    )


# ============================================================ 1. period reopen
def test_item1_reopen_can_be_raised_submitted_and_revoked_on_screen(c, p03, screens):
    assert_screen_operable(
        p03,
        screens,
        "M19-reopens",
        "M19-form-reopen",
        c.acct,
        ["close_id", "user_id", "end_datetime", "reason"],
        ["action_submit", "action_revoke"],
    )
    close = closed_period(c)
    end = fields.Datetime.now() + timedelta(days=1)
    p03.as_user(c.acct)
    made = p03.write(
        model="fix.period.reopen",
        values={
            "close_id": close.id,
            "user_id": c.acct2.id,
            "end_datetime": end.strftime("%Y-%m-%dT%H:%M"),
            "reason": "Late utility accrual",
        },
    )
    assert "id" in made, made
    reopen = c.env["fix.period.reopen"].browse(made["id"])
    assert reopen.state == "draft"
    res = p03.action(model="fix.period.reopen", ids=[reopen.id], method="action_submit")
    assert res["success"], res
    assert reopen.state == "pending" and reopen.requested_by_id == c.acct
    # the terms are what was submitted: the form refuses a change, the model too
    res = p03.write(model="fix.period.reopen", record_id=reopen.id, values={"user_id": c.acct.id})
    assert "error" in res and reopen.user_id == c.acct2
    with pytest.raises(UserError, match="frozen"):
        reopen.with_user(c.acct).write({"reason": "changed"})
    # the closer does not decide it; another administrator does, in the inbox
    assert not task_for(c, reopen, c.mgr)
    task_for(c, reopen, c.mgr2).with_user(c.mgr2).action_approve()
    assert reopen.state == "approved" and reopen.lock_exception_id
    # an accountant cannot revoke; an administrator can, from the same list
    p03.as_user(c.acct)
    assert not p03.action(model="fix.period.reopen", ids=[reopen.id], method="action_revoke")[
        "success"
    ]
    p03.as_user(c.mgr2)
    res = p03.action(model="fix.period.reopen", ids=[reopen.id], method="action_revoke")
    assert res["success"], res
    assert reopen.state == "revoked"


def test_item1_request_reopen_is_a_row_action_for_the_requester(c, p03, screens):
    acts = {a["m"]: a for a in screens["screens"]["M19-period-close"]["actions"]}
    assert (
        acts["action_request_reopen"]["kwarg"] == "reason" and acts["action_request_reopen"]["ask"]
    )
    close = closed_period(c)
    p03.as_user(c.acct2)
    res = p03.action(
        model="fix.period.close",
        ids=[close.id],
        method="action_request_reopen",
        kwargs={"reason": ""},
    )
    assert not res["success"] and "reason" in res["error"]
    res = p03.action(
        model="fix.period.close",
        ids=[close.id],
        method="action_request_reopen",
        kwargs={"reason": "Late accrual"},
    )
    assert res["success"], res
    reopen = c.env["fix.period.reopen"].search([("close_id", "=", close.id)])
    assert reopen.state == "pending" and reopen.user_id == c.acct2 and reopen.end_datetime


def test_item1_close_and_reopen_read_as_words_in_a_picker(c):
    close = closed_period(c)
    assert str(PE) in close.display_name and "fix.period.close" not in close.display_name


# ============================================================ 2. control flag
def test_item2_control_flag_change_is_operable_on_screen(c, p03, screens):
    assert_screen_operable(
        p03,
        screens,
        "M19-control-changes",
        "M19-form-control-change",
        c.acct,
        ["account_id", "new_is_control", "new_subledger", "reason"],
        ["action_submit"],
    )
    chart = c.env["fix.chart.account"].create(
        {
            "company_id": c.co.id,
            "account_code": "1-12-01-%03d" % next(_SEQ),
            "name": "Trade Receivables (control)",
            "account_type": "asset",
            "account_subtype": "receivable",
            "is_postable": True,
            "is_control_account": True,
            "control_subledger": "receivable",
            "statutory_group": "Trade and other receivables",
            "odoo_account_id": c.recv.id,
        }
    )
    p03.as_user(c.acct)
    made = p03.write(
        model="fix.chart.control.change",
        values={
            "account_id": chart.id,
            "new_is_control": False,
            "reason": "Re-mapped to a clearing account",
        },
    )
    assert "id" in made, made
    change = c.env["fix.chart.control.change"].browse(made["id"])
    assert p03.action(model="fix.chart.control.change", ids=[change.id], method="action_submit")[
        "success"
    ]
    assert change.state == "pending" and chart.is_control_account
    with pytest.raises(UserError, match="frozen"):
        change.with_user(c.acct).write({"new_is_control": True})
    task_for(c, change, c.mgr).with_user(c.mgr).action_approve()
    assert change.state == "applied" and not chart.is_control_account


# ============================================================ 5. re-route a journal
def test_item5_rejected_entry_is_rerouted_and_posts(c, p03):
    move, log = draft_je(c, c.acct, 1000.0)
    approval = move.fix_journal_approval_id
    p03.as_user(c.mgr)
    assert p03.je(move_id=move.id)["actions"]["approve"] is True
    task_for(c, approval, c.mgr).with_user(c.mgr).action_reject("Wrong cost centre")
    assert approval.state == "rejected" and move.state == "draft"

    p03.as_user(c.acct)
    view = p03.je(move_id=move.id)
    assert (
        view["approval"]["state"] == "rejected"
        and view["approval"]["rejection"] == "Wrong cost centre"
    )
    assert view["actions"] == {"approve": False, "route": True, "discard": True}
    res = p03.je_route(move_id=move.id, reason="Cost centre confirmed with the branch")
    assert res["success"], res
    assert (
        approval.state == "pending" and approval.reason == "Cost centre confirmed with the branch"
    )
    # the same entry cannot be routed twice while it waits
    assert not p03.je_route(move_id=move.id, reason="again")["success"]
    # the rejecter may decide again; the preparer still cannot
    assert task_for(c, approval, c.mgr) and not task_for(c, approval, c.acct)
    p03.as_user(c.mgr)
    res = p03.je_approve(move_id=move.id)
    assert res["success"], res
    assert move.state == "posted" and approval.state == "posted" and log.state == "posted"


def test_item5_voided_entry_is_rerouted_with_a_new_log_row(c, p03):
    move, log = draft_je(c, c.acct, 1000.0)
    p03.as_user(c.mgr)
    assert p03.je_approve(move_id=move.id)["success"]
    move.sudo().button_draft()
    approval = move.fix_journal_approval_id
    assert approval.state == "voided"
    p03.as_user(c.acct)
    assert p03.je(move_id=move.id)["actions"]["route"] is True
    res = p03.je_route(move_id=move.id, reason="Period corrected")
    assert res["success"], res
    assert approval.log_id != log and approval.log_id.state == "requested" and log.state == "posted"
    p03.as_user(c.mgr2)
    assert p03.je_approve(move_id=move.id)["success"]
    assert move.state == "posted" and approval.log_id.state == "posted"


def test_item5_entry_edited_after_routing_is_routed_again(c, p03):
    """The approve refusal says 'the preparer must route it again': he can now."""
    move, _log = draft_je(c, c.acct, 1000.0)
    approval = move.fix_journal_approval_id
    dr, cr_ = move.line_ids.sorted(lambda line: -line.debit)
    move.with_user(c.acct).write(
        {
            "line_ids": [
                Command.update(dr.id, {"debit": 9000.0}),
                Command.update(cr_.id, {"credit": 9000.0}),
            ]
        }
    )
    p03.as_user(c.mgr)
    assert p03.je(move_id=move.id)["actions"]["approve"] is False
    p03.as_user(c.acct)
    assert p03.je(move_id=move.id)["approval"]["changed_since_routed"] is True
    assert p03.je_route(move_id=move.id, reason="Amount corrected")["success"]
    assert approval.state == "pending"
    p03.as_user(c.mgr)
    assert p03.je_approve(move_id=move.id)["success"]
    assert move.state == "posted" and move.amount_total == 9000.0


def test_item5_draft_with_no_approval_is_routed_not_approved(c, p03):
    """The five live drafts: approve refuses them (J04 holds) and route gives them a path."""
    move = c.env["account.move"].with_user(c.acct).create(_vals(c, 30000.0, ref="Payroll GL"))
    p03.as_user(c.mgr)
    view = p03.je(move_id=move.id)
    assert view["approval"] is None and view["actions"]["approve"] is False
    res = p03.je_approve(move_id=move.id)
    assert not res["success"] and "Route it for approval" in res["error"]
    p03.as_user(c.acct2)
    assert p03.je(move_id=move.id)["actions"]["route"] is True
    res = p03.je_route(move_id=move.id, reason="Payroll September")
    assert res["success"], res
    approval = move.fix_journal_approval_id
    assert approval.state == "pending" and approval.dofa_tier_required == "tier_2"
    # the creator and the router are both out
    assert not task_for(c, approval, c.acct) and not task_for(c, approval, c.acct2)
    p03.as_user(c.mgr)
    assert p03.je_approve(move_id=move.id)["success"] and move.state == "posted"


def test_item5_earlier_requester_stays_excluded_after_a_reroute(c, p03):
    move, _log = draft_je(c, c.acct, 1000.0)
    approval = move.fix_journal_approval_id
    task_for(c, approval, c.mgr3).with_user(c.mgr3).action_reject("No")
    p03.as_user(c.mgr)
    assert p03.je_route(move_id=move.id, reason="round 2")["success"]
    task_for(c, approval, c.mgr3).with_user(c.mgr3).action_reject("No again")
    p03.as_user(c.mgr2)
    assert p03.je_route(move_id=move.id, reason="round 3")["success"]
    # mgr requested round 2: he is not asked in round 3
    assert not task_for(c, approval, c.mgr) and not task_for(c, approval, c.mgr2)
    assert task_for(c, approval, c.mgr3)


def test_item5_route_refuses_who_and_what_it_must(c, p03):
    move = c.env["account.move"].with_user(c.acct).create(_vals(c, 500.0, ref=""))
    for user in (c.plain, c.bill):
        p03.as_user(user)
        assert not p03.je_route(move_id=move.id, reason="x")["success"]
    assert not move.fix_journal_approval_id
    p03.as_user(c.acct)
    res = p03.je_route(move_id=move.id, reason="  ")
    assert not res["success"] and "reason" in res["error"]
    posted = sys_post(c, c.today)
    res = p03.je_route(move_id=posted.id, reason="x")
    assert not res["success"] and "not a draft" in res["error"]
    invoice = c.env["account.move"].create(
        {
            "move_type": "out_invoice",
            "partner_id": c.env["res.partner"].create({"name": "A08 op customer"}).id,
            "invoice_line_ids": [
                Command.create({"name": "x", "quantity": 1, "price_unit": 10.0, "tax_ids": []})
            ],
        }
    )
    assert p03.je(move_id=invoice.id)["actions"] == {
        "approve": False,
        "route": False,
        "discard": False,
    }
    res = p03.je_route(move_id=invoice.id, reason="x")
    assert not res["success"] and "not a manual journal" in res["error"]


