def test_item5_discard_cancels_and_says_so(c, p03):
    move, log = draft_je(c, c.acct, 1000.0)
    approval = move.fix_journal_approval_id
    task_for(c, approval, c.mgr).with_user(c.mgr).action_reject("Not ours")
    p03.as_user(c.acct2)
    assert p03.je(move_id=move.id)["actions"]["discard"] is False
    res = p03.je_discard(move_id=move.id, reason="not mine")
    assert not res["success"] and move.state == "draft"
    p03.as_user(c.acct)
    assert not p03.je_discard(move_id=move.id, reason=" ")["success"]
    res = p03.je_discard(move_id=move.id, reason="Raised on the wrong journal")
    assert res["success"], res
    assert move.state == "cancel" and approval.state == "voided"
    assert log.state == "discarded" and log.note == "Raised on the wrong journal"
    assert not p03.je_route(move_id=move.id, reason="back")["success"]
    # a leftover draft nobody routed: the administrator clears it
    left = c.env["account.move"].create(_vals(c, 70.0, ref="left behind"))
    p03.as_user(c.mgr)
    assert p03.je_discard(move_id=left.id, reason="orphan of a failed run")["success"]
    assert left.state == "cancel"


