# ============================================================ 7, 8. suspense
def test_item7_8_suspense_cutover_on_screen_as_an_accountant(c, p03):
    """The whole cutover: pending suspense blocks ready; the accountant's journal is
    approved; its number is set on the close; reconcile clears; ready passes."""
    entry = suspense_entry(c, 1200.0)
    close = worked_close(c)
    p03.as_user(c.acct)
    res = p03.action(model="fix.period.close", ids=[close.id], method="action_ready")
    assert not res["success"] and "still pending" in res["error"] and "1200.00" in res["error"]
    assert close.state == "in_progress"
    view = p03.close(close_id=close.id)["closes"][0]
    assert view["suspense_pending_count"] == 1 and view["suspense_pending_value"] == 1200.0
    # reconcile says what it needs
    res = p03.action(
        model="fix.period.close", ids=[close.id], method="action_reconcile_inventory_suspense"
    )
    assert not res["success"] and "cutover journal entry" in res["error"]

    susp = suspense_account(c)
    move, _log = draft_je(c, c.acct, 1200.0, credit=susp, ref="Suspense cutover")
    # neither a draft nor a made-up number can be set
    for number in (move.name or "/", "NOPE/1"):
        res = p03.action(
            model="fix.period.close",
            ids=[close.id],
            method="action_set_cutover_entry",
            kwargs={"entry": number},
        )
        assert not res["success"]
    p03.as_user(c.mgr)
    assert p03.je_approve(move_id=move.id)["success"]
    p03.as_user(c.acct)
    res = p03.action(
        model="fix.period.close",
        ids=[close.id],
        method="action_set_cutover_entry",
        kwargs={"entry": move.name},
    )
    assert res["success"], res
    assert close.cutover_move_id == move
    res = p03.action(
        model="fix.period.close", ids=[close.id], method="action_reconcile_inventory_suspense"
    )
    assert res["success"], res
    assert res["result"]["status"] == "zero_cleared" and entry.status == "reconciled"
    assert close.suspense_reconciled and close.cutover_voucher_ref == move.name
    res = p03.action(model="fix.period.close", ids=[close.id], method="action_ready")
    assert res["success"], res
    assert close.state == "ready_to_close"


