def test_item8_suspense_booked_after_ready_blocks_the_close(c):
    close = worked_close(c)
    close.with_user(c.acct).action_ready()
    assert close.state == "ready_to_close"
    entry = suspense_entry(c, 50.0)
    with pytest.raises(UserError, match="still pending"):
        close.with_user(c.mgr).action_close()
    assert close.state == "ready_to_close" and not c.co.fiscalyear_lock_date
    # archived or reconciled rows do not block, another company's do not either
    entry.sudo()._guarded().write({"status": "archived"})
    close.with_user(c.mgr).action_close()
    assert close.state == "closed"


# ============================================================ 9. step owner reads
def test_item9_step_owner_outside_finance_reads_and_completes_only_his_step(c, p03):
    evidence = "account.move,%d" % sys_post(c, date(2026, 9, 1)).id
    close = c.env["fix.period.close"].with_user(c.acct).create({"period_end": PE})
    close.with_user(c.acct).action_generate_standard_steps()
    p03.as_user(c.stk)
    data = p03.close()
    assert data["limited"] is True and data["next_period_end"] == ""
    row = next(r for r in data["closes"] if r["id"] == close.id)
    assert [s["sequence"] for s in row["steps"]] == [10]
    assert row["suspense_closing"] is None and row["suspense_pending_value"] is None
    res = p03.close_action(action="mark_done", step_id=row["steps"][0]["id"], evidence=evidence)
    assert res["success"], res
    assert close.line_ids.filtered(lambda s: s.sequence == 10).done_by_id == c.stk
    # his role opens only his own step
    other = close.line_ids.filtered(lambda s: s.sequence == 20)
    assert not p03.close_action(action="mark_done", step_id=other.id, evidence=evidence)["success"]
    assert other.state == "pending"
    # no step of yours, no console
    p03.as_user(c.plain)
    with pytest.raises(AccessError):
        p03.close()
    # finance reads everything
    p03.as_user(c.acct)
    data = p03.close()
    assert data["limited"] is False
    assert len(next(r for r in data["closes"] if r["id"] == close.id)["steps"]) == 10


